""", """const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Whether a slug retired at `retiredAt` is still held at `now`. The hold ends
 * at exactly `ORG_SLUG_HOLD_DAYS` days: from that instant the slug is released.
 */
function isHeld(retiredAt: string, now: Date): boolean {
  const releasedAt = Date.parse(retiredAt) + ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
  return now.getTime() < releasedAt;
}

/**
 * The one rule for turning a slug into a workspace (ADR 0005 §3): the live
 * workspace whose current slug it is, otherwise the live workspace that
 * retired it and still holds it. The session layer and every service lookup
 * come through here, so an old URL resolves — or stops resolving — the same
 * way everywhere. The returned row always carries the *current* slug.
 */
export async function findOrgBySlug(
  slug: string,
  now: Date = new Date(),
): Promise<Organization | null> {
  const db = getDb();

  const current = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (current) return toOrganization(current);

  const retired = db
    .select({ org: organizations, retiredAt: organizationRetiredSlugs.retiredAt })
    .from(organizationRetiredSlugs)
    .innerJoin(
      organizations,
      eq(organizations.id, organizationRetiredSlugs.orgId),
    )
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        isNull(organizations.archivedAt),
      ),
    )
    .all()
    .filter((row) => isHeld(row.retiredAt, now))
    .sort((a, b) => Date.parse(b.retiredAt) - Date.parse(a.retiredAt));

  const holder = retired[0];
  return holder ? toOrganization(holder.org) : null;
}
""")

