sub(p, """/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}
""", """/**
 * Whether `orgId` may take `slug` by rename (ADR 0005 §2). It may not while
 * any other workspace — live or deleted — has it as its current slug, nor
 * while another workspace holds it retired. A slug the workspace retired
 * itself never blocks it.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
  now: Date = new Date(),
): Promise<boolean> {
  const db = getDb();

  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (current) return false;

  const retiredElsewhere = db
    .select({ retiredAt: organizationRetiredSlugs.retiredAt })
    .from(organizationRetiredSlugs)
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        ne(organizationRetiredSlugs.orgId, orgId),
      ),
    )
    .all();

  return !retiredElsewhere.some((row) => isHeld(row.retiredAt, now));
}

/**
 * Moves a workspace from its current slug to `slug` in one transaction: the
 * slug being replaced is retired as of `now`, and if the workspace had retired
 * `slug` itself that retirement ends. Only the slug column is written — name,
 * plan and settings are untouched (ADR 0005 §7). The caller has already
 * checked the slug's shape and availability.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
  now: Date = new Date(),
): Promise<Organization> {
  const retiredAt = toIsoTimestamp(now);

  const row = getDb().transaction((tx) => {
    const current = tx
      .select({ slug: organizations.slug })
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    tx.delete(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.orgId, orgId),
          eq(organizationRetiredSlugs.slug, slug),
        ),
      )
      .run();

    tx.insert(organizationRetiredSlugs)
      .values({ orgId, slug: current.slug, retiredAt })
      .onConflictDoUpdate({
        target: [organizationRetiredSlugs.orgId, organizationRetiredSlugs.slug],
        set: { retiredAt },
      })
      .run();

    return tx
      .update(organizations)
      .set({ slug })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
  });

  return toOrganization(row);
}

/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. A slug
 * is taken while any workspace has it as its current slug or still holds it
 * retired, so a derived slug is suffixed past both.
 */
export async function listTakenOrgSlugs(
  prefix: string,
  now: Date = new Date(),
): Promise<readonly string[]> {
  const db = getDb();

  const current = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const held = db
    .select({
      slug: organizationRetiredSlugs.slug,
      retiredAt: organizationRetiredSlugs.retiredAt,
    })
    .from(organizationRetiredSlugs)
    .where(like(organizationRetiredSlugs.slug, `${prefix}%`))
    .all()
    .filter((row) => isHeld(row.retiredAt, now));

  return [...new Set([...current, ...held].map((row) => row.slug))];
}
""")
