    expect((await orgRepo.findOrgBySlug("beta"))?.id).toBe(b.org.id);
    // a can't go back to alpha now
    await expect(orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha" })).rejects.toBeInstanceOf(InvalidSlugError);

