/**
 * Renaming a workspace's URL slug — the rules of ADR 0005.
 *
 * The old slug is retired, not released: it keeps resolving to the workspace
 * everywhere a slug is resolved, and stays unavailable to everyone else, for
 * `ORG_SLUG_HOLD_DAYS` days. Each case builds its own tenants so the holds of
 * one case cannot leak into another.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import { renameOrganizationSlugSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import {
  createOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const HOLD_MS = ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
const T0 = new Date("2026-05-01T00:00:00.000Z");

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function captureSlugChanges(): TaskflowEventMap["organization.slug_changed"][] {
  const seen: TaskflowEventMap["organization.slug_changed"][] = [];
  detachers.push(
    subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function principalOf(tenant: Tenant): SessionPrincipal {
  return {
    userId: tenant.userIds.member,
    email: "member@example.test",
    activeOrgId: null,
    expiresAt: "2999-01-01T00:00:00.000Z" as IsoTimestamp,
  };
}

function freezeAt(msAfterT0: number): void {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date(T0.getTime() + msAfterT0));
}

async function slugChangeRows(tenant: Tenant) {
  const page = await listActivity(
    tenant.actors.admin,
    activityFilterSchema.parse({
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
    }),
  );
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlugSchema", () => {
  it("applies the shared slug rules to the new slug", () => {
    const orgId = "01HZZZAAAAAAAAAAAAAAAAAAAA";
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId, slug: "acme-inc" }).success,
    ).toBe(true);
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId, slug: "Acme Inc" }).success,
    ).toBe(false);
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId, slug: "settings" }).success,
    ).toBe(false);
  });
});

describe("renameOrganizationSlug", () => {
  it("changes only the slug and returns the workspace as stored", async () => {
    const tenant = await createTenant("rn-basic");
    const before = await orgRepo.findOrgById(tenant.org.id);

    const renamed = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rn-basic-next",
    });

    expect(renamed).toEqual({ ...before, slug: "rn-basic-next" });
    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(renamed);
  });

  it("shows the new slug wherever the workspace is read", async () => {
    const tenant = await createTenant("rn-read");
    await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rn-read-next",
    });

    const summary = await getOrganizationSummary(tenant.actors.member, tenant.org.id);
    expect(summary.organization.slug).toBe("rn-read-next");

    const listed = await listOrganizationsForUser(tenant.userIds.member);
    expect(listed.map((org) => org.slug)).toEqual(["rn-read-next"]);

    expect((await resolveOrgBySlug("rn-read-next"))?.id).toBe(tenant.org.id);
    const actor = await resolveActorForOrg(principalOf(tenant), "rn-read-next");
    expect(actor?.orgId).toBe(tenant.org.id);
  });

  it("needs the settings permission and stays inside the actor's workspace", async () => {
    const tenant = await createTenant("rn-perm");
    const other = await createTenant("rn-perm-other");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    await expect(
      renameOrganizationSlug(tenant.actors.member, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await resolveOrgBySlug("rn-perm-next")).toBeNull();
    expect(seen).toHaveLength(0);

    // An admin is enough: the product notes' "owner only" lost to the ADR.
    await expect(
      renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).resolves.toMatchObject({ slug: "rn-perm-next" });
  });

  it("refuses a malformed, reserved or taken slug without suffixing it", async () => {
    const tenant = await createTenant("rn-refuse");
    const other = await createTenant("rn-refuse-taken");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    for (const slug of ["Not A Slug", "settings", other.org.slug]) {
      await expect(
        renameOrganizationSlug(tenant.actors.owner, { orgId: tenant.org.id, slug }),
      ).rejects.toBeInstanceOf(InvalidSlugError);
    }

    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await slugChangeRows(tenant)).toHaveLength(0);
    expect(seen).toHaveLength(0);
  });

  it("treats a deleted workspace's slug as still taken", async () => {
    const tenant = await createTenant("rn-deleted");
    const gone = await createTenant("rn-deleted-gone");
    await orgRepo.archiveOrg(gone.org.id);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
