    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-chain-c",
    });

    freezeAt(HOLD_MS - 1);
    expect((await resolveOrgBySlug("rt-chain"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("rt-chain-b"))?.id).toBe(tenant.org.id);

    freezeAt(HOLD_MS);
    expect(await resolveOrgBySlug("rt-chain")).toBeNull();
    expect((await resolveOrgBySlug("rt-chain-b"))?.id).toBe(tenant.org.id);

