    const tenant = await createTenant("rt-back");
    const other = await createTenant("rt-back-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-back-next",
    });

    freezeAt(5 * MS_PER_DAY);
    const back = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-back",
    });
    expect(back.slug).toBe("rt-back");

    // The slug taken back is current again — no hold is counting down on it…
    freezeAt(HOLD_MS + MS_PER_DAY);
    expect((await resolveOrgBySlug("rt-back"))?.id).toBe(tenant.org.id);
    // …while the one it replaced is held from the second rename, not the first.
    expect((await resolveOrgBySlug("rt-back-next"))?.id).toBe(tenant.org.id);
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-back-next",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    freezeAt(5 * MS_PER_DAY + HOLD_MS);
    expect(await resolveOrgBySlug("rt-back-next")).toBeNull();
  });
});

