    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await resolveOrgBySlug("rn-perm-next")).toBeNull();
    expect(seen).toHaveLength(0);

    // An admin is enough: the product notes' "owner only" lost to the ADR.
    await expect(
      renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).resolves.toMatchObject({ slug: "rn-perm-next" });
  });

  it("refuses a malformed, reserved or taken slug without suffixing it", async () => {
    const tenant = await createTenant("rn-refuse");
    const other = await createTenant("rn-refuse-taken");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    for (const slug of ["Not A Slug", "settings", other.org.slug]) {
      await expect(
        renameOrganizationSlug(tenant.actors.owner, { orgId: tenant.org.id, slug }),
      ).rejects.toBeInstanceOf(InvalidSlugError);
    }

    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await slugChangeRows(tenant)).toHaveLength(0);
    expect(seen).toHaveLength(0);
  });

  it("treats a deleted workspace's slug as still taken", async () => {
    const tenant = await createTenant("rn-deleted");
    const gone = await createTenant("rn-deleted-gone");
    await orgRepo.archiveOrg(gone.org.id);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: gone.org.slug,
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("is a no-op when the slug is already current", async () => {
    const tenant = await createTenant("rn-noop");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    const result = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: tenant.org.slug,
    });

    expect(result).toEqual(before);
    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await slugChangeRows(tenant)).toHaveLength(0);
    expect(seen).toHaveLength(0);
  });

  it("publishes the event once and records the audit action once", async () => {
    const tenant = await createTenant("rn-announce");
    const seen = captureSlugChanges();
    // Attached as in production: the audit row must not be doubled by the bus.
    detachers.push(registerActivityListeners());

    await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rn-announce-next",
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "rn-announce",
      to: "rn-announce-next",
    });
    expect(seen[0]?.occurredAt).toEqual(expect.any(String));

    const rows = await slugChangeRows(tenant);
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "rn-announce", to: "rn-announce-next" },
    });
  });
});

describe("a retired slug", () => {
  it("keeps resolving to the workspace until the hold ends, then resolves to nothing", async () => {
    const tenant = await createTenant("rt-hold");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
