    freezeAt(HOLD_MS - 1);
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-take",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    freezeAt(HOLD_MS);
    const taken = await renameOrganizationSlug(other.actors.owner, {
      orgId: other.org.id,
      slug: "rt-take",
    });
    expect(taken.slug).toBe("rt-take");
    expect((await resolveOrgBySlug("rt-take"))?.id).toBe(other.org.id);

