import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import { renameOrganizationSlugSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import {
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import {
  createOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const HOLD_MS = ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
const T0 = new Date("2026-05-01T00:00:00.000Z");

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function captureSlugChanges(): TaskflowEventMap["organization.slug_changed"][] {
  const seen: TaskflowEventMap["organization.slug_changed"][] = [];
  detachers.push(
    subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function principalOf(tenant: Tenant): SessionPrincipal {
  return {
    userId: tenant.userIds.member,
    email: "member@example.test",
    activeOrgId: null,
    expiresAt: "2999-01-01T00:00:00.000Z" as IsoTimestamp,
  };
}

function freezeAt(msAfterT0: number): void {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date(T0.getTime() + msAfterT0));
}

async function slugChangeRows(tenant: Tenant) {
  const page = await listActivity(
    tenant.actors.admin,
    activityFilterSchema.parse({
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
    }),
  );
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlugSchema", () => {
  it("applies the shared slug rules to the new slug", () => {
    const orgId = "01HZZZAAAAAAAAAAAAAAAAAAAA";
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId, slug: "acme-inc" }).success,
    ).toBe(true);
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId, slug: "Acme Inc" }).success,
    ).toBe(false);
    expect(
      renameOrganizationSlugSchema.safeParse({ orgId, slug: "settings" }).success,
    ).toBe(false);
  });
});

describe("renameOrganizationSlug", () => {
  it("changes only the slug and returns the workspace as stored", async () => {
    const tenant = await createTenant("rn-basic");
    const before = await orgRepo.findOrgById(tenant.org.id);

    const renamed = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rn-basic-next",
    });

    expect(renamed).toEqual({ ...before, slug: "rn-basic-next" });
    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(renamed);
  });

  it("shows the new slug wherever the workspace is read", async () => {
    const tenant = await createTenant("rn-read");
    await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rn-read-next",
    });

    const summary = await getOrganizationSummary(tenant.actors.member, tenant.org.id);
    expect(summary.organization.slug).toBe("rn-read-next");

    const listed = await listOrganizationsForUser(tenant.userIds.member);
    expect(listed.map((org) => org.slug)).toEqual(["rn-read-next"]);

    expect((await resolveOrgBySlug("rn-read-next"))?.id).toBe(tenant.org.id);
    const actor = await resolveActorForOrg(principalOf(tenant), "rn-read-next");
    expect(actor?.orgId).toBe(tenant.org.id);
  });

  it("needs the settings permission and stays inside the actor's workspace", async () => {
    const tenant = await createTenant("rn-perm");
    const other = await createTenant("rn-perm-other");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    await expect(
      renameOrganizationSlug(tenant.actors.member, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await resolveOrgBySlug("rn-perm-next")).toBeNull();
    expect(seen).toHaveLength(0);

    // An admin is enough: the product notes' "owner only" lost to the ADR.
    await expect(
      renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
        slug: "rn-perm-next",
      }),
    ).resolves.toMatchObject({ slug: "rn-perm-next" });
  });

  it("refuses a malformed, reserved or taken slug without suffixing it", async () => {
    const tenant = await createTenant("rn-refuse");
    const other = await createTenant("rn-refuse-taken");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    for (const slug of ["Not A Slug", "settings", other.org.slug]) {
      await expect(
        renameOrganizationSlug(tenant.actors.owner, { orgId: tenant.org.id, slug }),
      ).rejects.toBeInstanceOf(InvalidSlugError);
    }

    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await slugChangeRows(tenant)).toHaveLength(0);
    expect(seen).toHaveLength(0);
  });

  it("treats a deleted workspace's slug as still taken", async () => {
    const tenant = await createTenant("rn-deleted");
    const gone = await createTenant("rn-deleted-gone");
    await orgRepo.archiveOrg(gone.org.id);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: gone.org.slug,
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("is a no-op when the slug is already current", async () => {
    const tenant = await createTenant("rn-noop");
    const seen = captureSlugChanges();
    const before = await orgRepo.findOrgById(tenant.org.id);

    const result = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: tenant.org.slug,
    });

    expect(result).toEqual(before);
    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);
    expect(await slugChangeRows(tenant)).toHaveLength(0);
    expect(seen).toHaveLength(0);
  });

  it("publishes the event once and records the audit action once", async () => {
    const tenant = await createTenant("rn-announce");
    const seen = captureSlugChanges();
    // Attached as in production: the audit row must not be doubled by the bus.
    detachers.push(registerActivityListeners());

    await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rn-announce-next",
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "rn-announce",
      to: "rn-announce-next",
    });
    expect(seen[0]?.occurredAt).toEqual(expect.any(String));

    const rows = await slugChangeRows(tenant);
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "rn-announce", to: "rn-announce-next" },
    });
  });
});

describe("a retired slug", () => {
  it("keeps resolving to the workspace until the hold ends, then resolves to nothing", async () => {
    const tenant = await createTenant("rt-hold");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-hold-next",
    });

    freezeAt(HOLD_MS - 1);
    const viaService = await resolveOrgBySlug("rt-hold");
    expect(viaService?.id).toBe(tenant.org.id);
    expect(viaService?.slug).toBe("rt-hold-next");
    expect((await orgRepo.findOrgBySlug("rt-hold"))?.id).toBe(tenant.org.id);
    const actor = await resolveActorForOrg(principalOf(tenant), "rt-hold");
    expect(actor).toMatchObject({ orgId: tenant.org.id, role: "member" });

    freezeAt(HOLD_MS);
    expect(await resolveOrgBySlug("rt-hold")).toBeNull();
    expect(await orgRepo.findOrgBySlug("rt-hold")).toBeNull();
    expect(await resolveActorForOrg(principalOf(tenant), "rt-hold")).toBeNull();
    expect((await resolveOrgBySlug("rt-hold-next"))?.id).toBe(tenant.org.id);
  });

  it("cannot be taken by another workspace until it is released", async () => {
    const tenant = await createTenant("rt-take");
    const other = await createTenant("rt-take-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-take-next",
    });

    freezeAt(HOLD_MS - 1);
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-take",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    freezeAt(HOLD_MS);
    const taken = await renameOrganizationSlug(other.actors.owner, {
      orgId: other.org.id,
      slug: "rt-take",
    });
    expect(taken.slug).toBe("rt-take");
    expect((await resolveOrgBySlug("rt-take"))?.id).toBe(other.org.id);

    // The first workspace gave it up for good once somebody else holds it.
    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "rt-take",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("is suffixed past at creation while held and free again afterwards", async () => {
    const tenant = await createTenant("rt-create");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-create-next",
    });

    freezeAt(HOLD_MS - 1);
    const during = await createOrganization(tenant.userIds.owner, {
      name: "During the hold",
      slug: "rt-create",
      plan: "free",
    });
    expect(during.slug).toBe("rt-create-2");

    freezeAt(HOLD_MS);
    const after = await createOrganization(tenant.userIds.owner, {
      name: "After the hold",
      slug: "rt-create",
      plan: "free",
    });
    expect(after.slug).toBe("rt-create");
  });

  it("stops resolving when its workspace is deleted, but stays held", async () => {
    const tenant = await createTenant("rt-gone");
    const other = await createTenant("rt-gone-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-gone-next",
    });
    await orgRepo.archiveOrg(tenant.org.id);

    expect(await resolveOrgBySlug("rt-gone")).toBeNull();
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-gone",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("keeps its own hold through a chain of renames", async () => {
    const tenant = await createTenant("rt-chain");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-chain-b",
    });
    freezeAt(10 * MS_PER_DAY);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-chain-c",
    });

    freezeAt(HOLD_MS - 1);
    expect((await resolveOrgBySlug("rt-chain"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("rt-chain-b"))?.id).toBe(tenant.org.id);

    freezeAt(HOLD_MS);
    expect(await resolveOrgBySlug("rt-chain")).toBeNull();
    expect((await resolveOrgBySlug("rt-chain-b"))?.id).toBe(tenant.org.id);

    freezeAt(10 * MS_PER_DAY + HOLD_MS);
    expect(await resolveOrgBySlug("rt-chain-b")).toBeNull();
    expect((await resolveOrgBySlug("rt-chain-c"))?.slug).toBe("rt-chain-c");
  });

  it("can be taken back by its own workspace, which retires the slug it replaces", async () => {
    const tenant = await createTenant("rt-back");
    const other = await createTenant("rt-back-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-back-next",
    });

    freezeAt(5 * MS_PER_DAY);
    const back = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-back",
    });
    expect(back.slug).toBe("rt-back");

    // The slug taken back is current again — no hold is counting down on it…
    freezeAt(HOLD_MS + MS_PER_DAY);
    expect((await resolveOrgBySlug("rt-back"))?.id).toBe(tenant.org.id);
    // …while the one it replaced is held from the second rename, not the first.
    expect((await resolveOrgBySlug("rt-back-next"))?.id).toBe(tenant.org.id);
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-back-next",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    freezeAt(5 * MS_PER_DAY + HOLD_MS);
    expect(await resolveOrgBySlug("rt-back-next")).toBeNull();
  });
});

