    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "rn-announce", to: "rn-announce-next" },
    });
  });
});

describe("a retired slug", () => {
  it("keeps resolving to the workspace until the hold ends, then resolves to nothing", async () => {
    const tenant = await createTenant("rt-hold");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-hold-next",
    });

    freezeAt(HOLD_MS - 1);
    const viaService = await resolveOrgBySlug("rt-hold");
    expect(viaService?.id).toBe(tenant.org.id);
    expect(viaService?.slug).toBe("rt-hold-next");
    expect((await orgRepo.findOrgBySlug("rt-hold"))?.id).toBe(tenant.org.id);
    const actor = await resolveActorForOrg(principalOf(tenant), "rt-hold");
    expect(actor).toMatchObject({ orgId: tenant.org.id, role: "member" });

    freezeAt(HOLD_MS);
    expect(await resolveOrgBySlug("rt-hold")).toBeNull();
    expect(await orgRepo.findOrgBySlug("rt-hold")).toBeNull();
    expect(await resolveActorForOrg(principalOf(tenant), "rt-hold")).toBeNull();
    expect((await resolveOrgBySlug("rt-hold-next"))?.id).toBe(tenant.org.id);
  });

  it("cannot be taken by another workspace until it is released", async () => {
    const tenant = await createTenant("rt-take");
    const other = await createTenant("rt-take-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-take-next",
    });

    freezeAt(HOLD_MS - 1);
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-take",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    freezeAt(HOLD_MS);
    const taken = await renameOrganizationSlug(other.actors.owner, {
      orgId: other.org.id,
      slug: "rt-take",
    });
    expect(taken.slug).toBe("rt-take");
    expect((await resolveOrgBySlug("rt-take"))?.id).toBe(other.org.id);

    // The first workspace gave it up for good once somebody else holds it.
    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "rt-take",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("is suffixed past at creation while held and free again afterwards", async () => {
    const tenant = await createTenant("rt-create");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-create-next",
    });

    freezeAt(HOLD_MS - 1);
    const during = await createOrganization(tenant.userIds.owner, {
      name: "During the hold",
      slug: "rt-create",
      plan: "free",
    });
    expect(during.slug).toBe("rt-create-2");

    freezeAt(HOLD_MS);
    const after = await createOrganization(tenant.userIds.owner, {
      name: "After the hold",
      slug: "rt-create",
      plan: "free",
    });
    expect(after.slug).toBe("rt-create");
  });

  it("stops resolving when its workspace is deleted, but stays held", async () => {
    const tenant = await createTenant("rt-gone");
    const other = await createTenant("rt-gone-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-gone-next",
    });
    await orgRepo.archiveOrg(tenant.org.id);

    expect(await resolveOrgBySlug("rt-gone")).toBeNull();
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-gone",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("keeps its own hold through a chain of renames", async () => {
    const tenant = await createTenant("rt-chain");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-chain-b",
    });
    freezeAt(10 * MS_PER_DAY);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-chain-c",
    });

    freezeAt(HOLD_MS - 1);
    expect((await resolveOrgBySlug("rt-chain"))?.id).toBe(tenant.org.id);
    expect((await resolveOrgBySlug("rt-chain-b"))?.id).toBe(tenant.org.id);

    freezeAt(HOLD_MS);
    expect(await resolveOrgBySlug("rt-chain")).toBeNull();
    expect((await resolveOrgBySlug("rt-chain-b"))?.id).toBe(tenant.org.id);

    freezeAt(10 * MS_PER_DAY + HOLD_MS);
    expect(await resolveOrgBySlug("rt-chain-b")).toBeNull();
    expect((await resolveOrgBySlug("rt-chain-c"))?.slug).toBe("rt-chain-c");
  });

  it("can be taken back by its own workspace, which retires the slug it replaces", async () => {
    const tenant = await createTenant("rt-back");
    const other = await createTenant("rt-back-other");
    freezeAt(0);
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-back-next",
    });

    freezeAt(5 * MS_PER_DAY);
    const back = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rt-back",
    });
    expect(back.slug).toBe("rt-back");

    // The slug taken back is current again — no hold is counting down on it…
    freezeAt(HOLD_MS + MS_PER_DAY);
    expect((await resolveOrgBySlug("rt-back"))?.id).toBe(tenant.org.id);
    // …while the one it replaced is held from the second rename, not the first.
    expect((await resolveOrgBySlug("rt-back-next"))?.id).toBe(tenant.org.id);
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: other.org.id,
        slug: "rt-back-next",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    freezeAt(5 * MS_PER_DAY + HOLD_MS);
    expect(await resolveOrgBySlug("rt-back-next")).toBeNull();
  });
});

